// Розгортання + розбір призначення платежу ПРАВИЛАМИ. Модель тут ще не потрібна.
const RX_DOC = /(?:рах(?:унк|унок|\.)?|накладн\w*|інвойс|invoice|№)\s*№?\s*([A-Za-zА-Яа-яІіЇїЄєҐґ0-9][A-Za-zА-Яа-яІіЇїЄєҐґ0-9\-\/]{1,20})/gi;
const RX_VAT = /ПДВ[^0-9]{0,12}([0-9][0-9 ,\.]*)/i;
const RX_CONTRACT = /догов\w*\s*№?\s*([A-Za-zА-Яа-я0-9\-\/]{1,20})/i;
const client = $('Активні клієнти').first().json.client_id;
const out = [];

for (const item of $input.all()) {
  const rows = item.json.transactions ?? item.json.data ?? [];
  for (const t of rows) {
    const purpose = String(t.OSND ?? t.purpose ?? '').trim();
    const docs = [...purpose.matchAll(RX_DOC)].map(m => m[1]).filter((v, i, a) => a.indexOf(v) === i);
    const vat = (purpose.match(RX_VAT) || [])[1];
    const contract = (purpose.match(RX_CONTRACT) || [])[1];
    out.push({ json: {
      client_id: client,
      ext_id: String(t.ID ?? t.id ?? t.REF ?? ''),
      account_iban: String(t.AUT_MY_ACC ?? $env.P24_IBAN ?? ''),
      op_date: String(t.DAT_OD ?? t.date ?? '').slice(0, 10),
      amount: Math.abs(Number(String(t.SUM ?? t.amount ?? '0').replace(',', '.'))),
      direction: String(t.TRANTYPE ?? t.direction ?? 'D') === 'C' ? 'in' : 'out',
      cp_edrpou: String(t.AUT_CNTR_CRF ?? t.counterparty_edrpou ?? '').trim(),
      cp_name: String(t.AUT_CNTR_NAM ?? t.counterparty_name ?? '').trim(),
      purpose,
      parsed: { doc_numbers: docs, vat: vat ? Number(vat.replace(/\s/g, '').replace(',', '.')) : null, contract: contract ?? null }
    }});
  }
}
return out;
